head.script:
scwin.screenId = "jldbnf10000";

///////// 1. 변수 및 선언 영역 /////////

scwin.rownum = 0;

scwin.apct_tel_no = undefined;

scwin.apct_fax_no = undefined;

scwin.encryp_apct_email = undefined;

scwin.encryp_cellphone_no = undefined;

scwin.rep_majagnt_com_tel_no = undefined;

scwin.rep_majagnt_com_fax_no = undefined;

scwin.encryp_rep_majagnt_com_email = undefined;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.i = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "ipt_cfiCd", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'GB'); } }, { id: "ipt_cfiCd_2", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "ipt_cfiCd_3", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'AB'); } }, { id: "c_when_194", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_196", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }, { id: "c_when_201", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_when_294", fn: function(){ return (String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "c_otherwise_307", fn: function(){ return (!((String((dma_companyInfoVO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "companyInfoVO.isurCd"); })())).substring(0, 2) === 'MB'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bndMktactTpCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bndMktactTpCd")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_datefmt_cal_fstIntPayDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_fstIntPayDd = function () { $c.date.checkCalendarFormat("cal_fstIntPayDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_datefmt_cal_saleDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_saleDd = function () { $c.date.checkCalendarFormat("cal_saleDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const header_cd = $c.util.getComponent('ipt_bndMktactTpCd').getValue();
        if (header_cd === '112') {
            dmenus = { "bmenu": 1, "mmenu": 9 };
        } else {
            if (header_cd === '122') {
                dmenus = { "bmenu": 1, "mmenu": 9 };
            } else {
                if (header_cd === '132') {
                    dmenus = { "bmenu": 1, "mmenu": 9 };
                } else {
                    if (header_cd === '142') {
                        dmenus = { "bmenu": 1, "mmenu": 9 };
                    } else {
                        if (header_cd === '301') {
                            dmenus = { "bmenu": 1, "mmenu": 9 };
                        }
                    }
                }
            }
        }
        $('div#header').trigger('mouseleave');
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf10000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(>- vs bloclisting) — 어느 쪽인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.v_str = '' + dma_result.get("curr_tp_cd") + '';

scwin.v_int_pay_mth = '' + dma_result.get("int_pay_methd_cd") + '';

scwin.v_int_set_std_int = '' + dma_result.get("intRtDecsnMiscBasIntNm") + '';

scwin.v_c_std_int = '' + dma_result.get("coupnRtDecsnBasIntCd") + '';

scwin.v_rdmp_mth = '' + dma_result.get("redmpt_methd_tp_cd") + '';

scwin.v_div_rdmp_cd = '' + dma_result.get("splitRedmptTpCd") + '';

scwin.v_str1 = '' + dma_result.get("regInstCd") + '';

scwin.v_str2 = '' + dma_result.get("regInstNm") + '';

scwin.v_flag = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "flag" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("flag"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "flag" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("flag")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "flag" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("flag"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "flag" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("flag"))));

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_datefmt_cal_fstIntPayDd();
        scwin.init_datefmt_cal_saleDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf10000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

