        if (($c.util.getComponent('ipt_intPayMethdCd_7').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_8').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_9').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_10').getValue() !== '')) {
            $c.util.getComponent('dma_TempSaveCheckValuesReq').set('cfiCd', 'DBVUFB');
        } else {
            if (($c.util.getComponent('ipt_intPayMethdCd').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_2').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_3').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_5').getValue() !== '') || ($c.util.getComponent('ipt_intPayMethdCd_6').getValue() !== '')) {
                $c.util.getComponent('dma_TempSaveCheckValuesReq').set('cfiCd', 'DBFUFB');
            } else {
                if (($c.util.getComponent('ipt_intPayMethdCd_4').getValue() !== '')) {
                    $c.util.getComponent('dma_TempSaveCheckValuesReq').set('cfiCd', 'DBZUFB');
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


